void need(bool yes,const char* why){if(!yes)throw FormatError(why);}
template<class F>void rejects(F&& f,std::string_view reason){std::string actual;bool rejected=false;try{f();}catch(const std::exception&e){actual=e.what();rejected=std::string_view(e.what()).find(reason)!=std::string_view::npos;}if(!rejected)throw FormatError("Expected query-service rejection ["+std::string(reason)+"], got ["+actual+"]");}
unsigned word(PhysicsLiveWorldTu15&w,unsigned at){return Bytes(w.memory().view(at,4)).u32(0);}
unsigned aux(PhysicsLiveWorldTu15&w){return word(w,word(w,0x4f3cd8u)+4);}
